function decodeEntities(s) {
  if (!s) return s;
  const map = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', '#39': "'" };
  return s
    .replace(/&#x([0-9a-fA-F]+);/g, (_, h) => String.fromCodePoint(parseInt(h, 16)))
    .replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(parseInt(d, 10)))
    .replace(/&([a-zA-Z#0-9]+);/g, (m, name) => map[name] !== undefined ? map[name] : m);
}

function stripTags(s) {
  return decodeEntities(String(s).replace(/<[^>]*>/g, ' ')).replace(/\s+/g, ' ').trim();
}

function pick(block, tags) {
  for (const tag of tags) {
    const re = new RegExp('<' + tag + '(?:\\s[^>]*)?>([\\s\\S]*?)<\\/' + tag + '>', 'i');
    const m = block.match(re);
    if (m && m[1] !== undefined) {
      let v = m[1].trim();
      const cdata = v.match(/^<!\[CDATA\[([\s\S]*?)\]\]>$/);
      if (cdata) v = cdata[1];
      return v;
    }
  }
  return null;
}

function extractLink(block, isAtom) {
  if (isAtom) {
    const m = block.match(/<link[^>]*href=["']([^"']+)["'][^>]*\/>/i);
    if (m) return decodeEntities(m[1]);
    return pick(block, ['link']);
  }
  return pick(block, ['link']);
}

const raw = String(config.raw_xml || '');
const maxItems = Math.max(1, Math.min(500, Number(config.max_items) || 50));

const isAtom = /<feed[\s>]/i.test(raw) && /<entry[\s>]/i.test(raw);
const isRss = /<rss[\s>]|<channel[\s>]/i.test(raw);
const feedFormat = isAtom ? 'atom' : (isRss ? 'rss' : null);

const itemRe = isAtom ? /<entry(?:\s[^>]*)?>([\s\S]*?)<\/entry>/gi : /<item(?:\s[^>]*)?>([\s\S]*?)<\/item>/gi;

const items = [];
let m;
while ((m = itemRe.exec(raw)) !== null && items.length < maxItems) {
  const block = m[1];
  const title = pick(block, ['title']);
  const link = extractLink(block, isAtom);
  const id = pick(block, isAtom ? ['id'] : ['guid']) || link;
  const snippetRaw = pick(block, ['description', 'summary', 'content:encoded', 'content']);
  const snippet = snippetRaw != null ? stripTags(snippetRaw).slice(0, 300) || null : null;
  const published = pick(block, ['pubDate', 'published', 'updated', 'dc:date']);
  items.push({
    id: id ? decodeEntities(id) : null,
    title: title ? stripTags(title) || null : null,
    link: link ? decodeEntities(link) : null,
    snippet: snippet,
    published: published ? decodeEntities(published) : null
  });
}

return { items: items, count: items.length, feed_format: feedFormat };
